def loss_relations(self, outputs, targets, indices, num_boxes):
    losses = []

    for i, ((src_index, target_index), target) in enumerate(
            zip(indices, targets)
    ):
        full_index = torch.arange(self.num_object_queries)
        uniques, counts = torch.cat([full_index, src_index]).unique(
            return_counts=True
        )
        full_src_index = torch.cat([src_index, uniques[counts == 1]])
        full_target_index = torch.cat(
            [target_index, torch.arange(len(target_index), self.num_object_queries)]
        )

        pred_rel = outputs["pred_rel"][i, full_src_index][
                   :, full_src_index
                   ]  # [num_obj_queries, num_obj_queries, config.num_rel_labels]
        target_rel = target["rel"][full_target_index][
                     :, full_target_index
                     ]  # [num_obj_queries, num_obj_queries, config.num_rel_labels]

        pred_rel=pred_rel+self.tau* self.model.transformer.decoder.rel_dist.log().to(
        pred_rel.device
    )
        rel_index = torch.nonzero(target_rel)
        num_rel = rel_index.shape[0]
        num_rel = max(num_rel, 1)
        pred_rel=pred_rel.view(1,-1,self.num_rel_labels)
        target_rel=target_rel.view(1,-1,self.num_rel_labels)
        loss=sigmoid_focal_loss(pred_rel, target_rel, num_rel)*40000

        losses.append(loss)

    losses = {
        "loss_rel": torch.stack(losses).sum(),
    }
    return losses


def get_loss(self, loss, outputs, targets, indices, num_boxes, **kwargs):
    loss_map = {
        'labels': self.loss_labels,
        'cardinality': self.loss_cardinality,
        'boxes': self.loss_boxes,
        'masks': self.loss_masks,
        'relations': self.loss_relations,
        'conf': self.loss_confidence,
        'salient_full_conf': self.loss_salient_full_conf
    }
    assert loss in loss_map, f'do you really want to compute {loss} loss?'
    return loss_map[loss](outputs, targets, indices, num_boxes, **kwargs)

